  1→import { useState } from "react";
  2→import { supabase } from "@/integrations/supabase/client";
  3→import { Button } from "@/components/ui/button";
  4→import { Input } from "@/components/ui/input";
  5→import { Label } from "@/components/ui/label";
  6→import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
  7→import { toast } from "sonner";
  8→import { Loader2 } from "lucide-react";
  9→
 10→interface AuthFormProps {
 11→  defaultTab?: "signin" | "signup";
 12→  onSuccess?: () => void;
 13→}
 14→
 15→const AuthForm = ({ defaultTab = "signin", onSuccess }: AuthFormProps) => {
 16→  const [email, setEmail] = useState("");
 17→  const [password, setPassword] = useState("");
 18→  const [confirmPassword, setConfirmPassword] = useState("");
 19→  const [loading, setLoading] = useState(false);
 20→
 21→  const handleSignUp = async (e: React.FormEvent) => {
 22→    e.preventDefault();
 23→    if (password !== confirmPassword) {
 24→      toast.error("Passwords do not match");
 25→      return;
 26→    }
 27→    setLoading(true);
 28→    try {
 29→      const { error } = await supabase.auth.signUp({
 30→        email,
 31→        password,
 32→        options: { emailRedirectTo: window.location.origin },
 33→      });
 34→      if (error) {
 35→        toast.error(error.message);
 36→      } else {
 37→        toast.success("Check your email to confirm your account!");
 38→        onSuccess?.();
 39→      }
 40→    } catch (err) {
 41→      console.error("Unexpected sign-up error:", err);
 42→      toast.error("An unexpected error occurred. Please try again.");
 43→    } finally {
 44→      setLoading(false);
 45→    }
 46→  };
 47→
 48→  const handleSignIn = async (e: React.FormEvent) => {
 49→    e.preventDefault();
 50→    setLoading(true);
 51→    try {
 52→      const { error } = await supabase.auth.signInWithPassword({ email, password });
 53→      if (error) {
 54→        toast.error(error.message);
 55→      } else {
 56→        onSuccess?.();
 57→      }
 58→    } catch (err) {
 59→      console.error("Unexpected sign-in error:", err);
 60→      toast.error("An unexpected error occurred. Please try again.");
 61→    } finally {
 62→      setLoading(false);
 63→    }
 64→  };
 65→
 66→  const handleMagicLink = async () => {
 67→    if (!email) {
 68→      toast.error("Enter your email first");
 69→      return;
 70→    }
 71→    setLoading(true);
 72→    try {
 73→      const { error } = await supabase.auth.signInWithOtp({
 74→        email,
 75→        options: { emailRedirectTo: window.location.origin },
 76→      });
 77→      if (error) toast.error(error.message);
 78→      else toast.success("Magic link sent! Check your email.");
 79→    } catch (err) {
 80→      console.error("Unexpected magic link error:", err);
 81→      toast.error("An unexpected error occurred. Please try again.");
 82→    } finally {
 83→      setLoading(false);
 84→    }
 85→  };
 86→
 87→  return (
 88→    <Tabs defaultValue={defaultTab} className="w-full">
 89→      <TabsList className="grid w-full grid-cols-2 mb-6">
 90→        <TabsTrigger value="signin">Sign In</TabsTrigger>
 91→        <TabsTrigger value="signup">Sign Up</TabsTrigger>
 92→      </TabsList>
 93→      <TabsContent value="signin">
 94→        <form onSubmit={handleSignIn} className="space-y-4">
 95→          <div className="space-y-2">
 96→            <Label htmlFor="signin-email">Email</Label>
 97→            <Input id="signin-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@company.com" required />
 98→          </div>
 99→          <div className="space-y-2">
100→            <Label htmlFor="signin-password">Password</Label>
101→            <Input id="signin-password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" required />
102→          </div>
103→          <Button type="submit" className="w-full" disabled={loading}>
104→            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
105→            Sign In
106→          </Button>
107→          <Button type="button" variant="outline" className="w-full" onClick={handleMagicLink} disabled={loading}>
108→            Send Magic Link
109→          </Button>
110→        </form>
111→      </TabsContent>
112→      <TabsContent value="signup">
113→        <form onSubmit={handleSignUp} className="space-y-4">
114→          <div className="space-y-2">
115→            <Label htmlFor="signup-email">Email</Label>
116→            <Input id="signup-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@company.com" required />
117→          </div>
118→          <div className="space-y-2">
119→            <Label htmlFor="signup-password">Password</Label>
120→            <Input id="signup-password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Min 6 characters" required minLength={6} />
121→          </div>
122→          <div className="space-y-2">
123→            <Label htmlFor="signup-confirm-password">Confirm Password</Label>
124→            <Input id="signup-confirm-password" type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Repeat password" required minLength={6} />
125→            {confirmPassword && password !== confirmPassword && (
126→              <p className="text-xs text-destructive">Passwords do not match</p>
127→            )}
128→          </div>
129→          <Button type="submit" className="w-full" disabled={loading || (!!confirmPassword && password !== confirmPassword)}>
130→            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
131→            Create Account
132→          </Button>
133→        </form>
134→      </TabsContent>
135→    </Tabs>
136→  );
137→};
138→
139→export default AuthForm;
140→

  1→import { useState } from "react";
  2→import { useQuery } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { useAuth } from "@/hooks/useAuth";
  5→import {
  6→  Dialog,
  7→  DialogContent,
  8→  DialogDescription,
  9→  DialogHeader,
 10→  DialogTitle,
 11→  DialogTrigger,
 12→} from "@/components/ui/dialog";
 13→import { Button } from "@/components/ui/button";
 14→import { Input } from "@/components/ui/input";
 15→import { Badge } from "@/components/ui/badge";
 16→import { toast } from "sonner";
 17→import { Coins, Loader2, ShoppingCart, Sparkles, Crown, Wallet } from "lucide-react";
 18→import SubscriptionDialog from "@/components/SubscriptionDialog";
 19→
 20→interface BuyCreditsDialogProps {
 21→  trigger?: React.ReactNode;
 22→}
 23→
 24→const QUICK_AMOUNTS = [5, 10, 25, 50];
 25→
 26→const BuyCreditsDialog = ({ trigger }: BuyCreditsDialogProps) => {
 27→  const { user } = useAuth();
 28→  const [open, setOpen] = useState(false);
 29→  const [amount, setAmount] = useState("");
 30→  const [buying, setBuying] = useState(false);
 31→
 32→  const { data: config } = useQuery({
 33→    queryKey: ["platform_config_topup"],
 34→    queryFn: async () => {
 35→      const { data, error } = await supabase
 36→        .from("platform_config")
 37→        .select("payg_per_resume_cost, topup_min_amount")
 38→        .limit(1)
 39→        .single();
 40→      if (error) throw error;
 41→      return data as any;
 42→    },
 43→  });
 44→
 45→  const perResumeCost = config?.payg_per_resume_cost ?? 0.07;
 46→  const minAmount = config?.topup_min_amount ?? 1;
 47→  const numericAmount = parseFloat(amount) || 0;
 48→  const calculatedCredits = perResumeCost > 0 ? Math.floor(numericAmount / perResumeCost) : 0;
 49→  const isValid = numericAmount >= minAmount;
 50→
 51→  const handleBuy = async () => {
 52→    if (!user || !isValid) return;
 53→    setBuying(true);
 54→
 55→    try {
 56→      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
 57→        body: {
 58→          topup_amount: numericAmount,
 59→          return_url: `${window.location.origin}/payment/callback`,
 60→        },
 61→      });
 62→
 63→      if (error) throw error;
 64→
 65→      if (!data?.checkout_url) {
 66→        toast.error(data?.error || "Failed to create checkout session");
 67→        return;
 68→      }
 69→
 70→      window.location.href = data.checkout_url;
 71→    } catch (err: any) {
 72→      toast.error(err.message);
 73→    } finally {
 74→      setBuying(false);
 75→    }
 76→  };
 77→
 78→  return (
 79→    <Dialog open={open} onOpenChange={setOpen}>
 80→      <DialogTrigger asChild>
 81→        {trigger || (
 82→          <Button variant="outline" className="gap-2">
 83→            <ShoppingCart className="h-4 w-4" />
 84→            Buy Credits
 85→          </Button>
 86→        )}
 87→      </DialogTrigger>
 88→      <DialogContent className="sm:max-w-md">
 89→        <DialogHeader>
 90→          <DialogTitle className="flex items-center gap-2">
 91→            <Sparkles className="h-5 w-5 text-primary" />
 92→            Add Credits
 93→          </DialogTitle>
 94→          <DialogDescription>
 95→            Enter any amount to recharge your wallet. Credits never expire.
 96→          </DialogDescription>
 97→        </DialogHeader>
 98→
 99→        <div className="space-y-4 pt-2">
100→          {/* Quick amount buttons */}
101→          <div className="flex gap-2 flex-wrap">
102→            {QUICK_AMOUNTS.filter(a => a >= minAmount).map((a) => (
103→              <Button
104→                key={a}
105→                variant={numericAmount === a ? "default" : "outline"}
106→                size="sm"
107→                className="flex-1 min-w-[60px]"
108→                onClick={() => setAmount(String(a))}
109→              >
110→                ${a}
111→              </Button>
112→            ))}
113→          </div>
114→
115→          {/* Amount input */}
116→          <div>
117→            <label className="text-sm font-medium text-foreground mb-1.5 block">
118→              Custom Amount (USD)
119→            </label>
120→            <div className="relative">
121→              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
122→              <Input
123→                type="number"
124→                step="0.5"
125→                min={minAmount}
126→                placeholder={String(minAmount)}
127→                value={amount}
128→                onChange={(e) => setAmount(e.target.value)}
129→                className="pl-7 text-lg font-semibold"
130→                autoFocus
131→              />
132→            </div>
133→            <p className="text-[11px] text-muted-foreground mt-1">
134→              Minimum: ${minAmount}
135→            </p>
136→          </div>
137→
138→          {/* Credit preview */}
139→          {numericAmount > 0 && (
140→            <div className="rounded-lg bg-accent/50 border border-border p-4 text-center">
141→              <div className="flex items-center justify-center gap-2">
142→                <Wallet className="h-5 w-5 text-primary" />
143→                <span className="text-sm text-muted-foreground">You'll get</span>
144→              </div>
145→              <div className="flex items-center justify-center gap-2 mt-1">
146→                <Badge className="gap-1 text-base px-3 py-1">
147→                  <Coins className="h-4 w-4" />
148→                  {calculatedCredits} credits
149→                </Badge>
150→              </div>
151→              <p className="text-[11px] text-muted-foreground mt-2">
152→                1 credit = 1 resume ranked • ${perResumeCost}/credit
153→              </p>
154→            </div>
155→          )}
156→
157→          {/* Pay button */}
158→          <Button
159→            className="w-full"
160→            size="lg"
161→            onClick={handleBuy}
162→            disabled={buying || !isValid}
163→          >
164→            {buying ? (
165→              <Loader2 className="h-4 w-4 animate-spin mr-2" />
166→            ) : null}
167→            {numericAmount > 0 ? `Pay $${numericAmount.toFixed(2)}` : "Enter an amount"}
168→          </Button>
169→        </div>
170→
171→        {/* Subscription upsell */}
172→        <div className="rounded-lg bg-primary/5 border border-primary/20 px-4 py-3 flex items-center justify-between">
173→          <div className="flex items-center gap-2">
174→            <Crown className="h-4 w-4 text-primary" />
175→            <p className="text-xs font-medium text-foreground">Save more with a subscription plan</p>
176→          </div>
177→          <SubscriptionDialog
178→            trigger={
179→              <Button variant="ghost" size="sm" className="h-7 text-xs text-primary hover:text-primary gap-1">
180→                View Plans →
181→              </Button>
182→            }
183→          />
184→        </div>
185→      </DialogContent>
186→    </Dialog>
187→  );
188→};
189→
190→export default BuyCreditsDialog;
191→

 1→import { useAuth } from "@/hooks/useAuth";
 2→import SidebarLayout from "@/components/SidebarLayout";
