  1→import { useCallback, useEffect, useState } from "react";
  2→import SidebarLayout from "@/components/SidebarLayout";
  3→import ChangePasswordCard from "@/components/settings/ChangePasswordCard";
  4→import { useAuth } from "@/hooks/useAuth";
  5→import { supabase } from "@/integrations/supabase/client";
  6→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  7→import { Badge } from "@/components/ui/badge";
  8→import { Separator } from "@/components/ui/separator";
  9→import { Skeleton } from "@/components/ui/skeleton";
 10→import { Mail, Calendar, Briefcase, FileText, Zap, Inbox, Crown } from "lucide-react";
 11→import { FadeIn } from "@/components/ui/fade-in";
 12→import { StaggerList } from "@/components/ui/stagger-list";
 13→
 14→function getInitials(email?: string | null): string {
 15→  if (!email) return "?";
 16→  const name = email.split("@")[0];
 17→  const parts = name.split(/[._-]/);
 18→  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
 19→  return name[0]?.toUpperCase() || "?";
 20→}
 21→
 22→function getUserName(email?: string | null): string {
 23→  if (!email) return "User";
 24→  return email.split("@")[0].replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
 25→}
 26→
 27→const Profile = () => {
 28→  const { user, profile } = useAuth();
 29→  const plan = profile?.plan ?? "free";
 30→  const isPaid = plan !== "free";
 31→
 32→  // Fetch usage stats
 33→  const [stats, setStats] = useState<{ totalJobs: number; totalResumes: number; creditsUsed: number } | null>(null);
 34→  const fetchStats = useCallback(async () => {
 35→    if (!user) return;
 36→    try {
 37→      const [jobsRes, usageRes] = await Promise.all([
 38→        supabase.from("jobs").select("id, resumes(count)").eq("user_id", user.id),
 39→        supabase.from("usage_logs").select("credits_used").eq("user_id", user.id),
 40→      ]);
 41→      const jobs = jobsRes.data ?? [];
 42→      const totalJobs = jobs.length;
 43→      const totalResumes = jobs.reduce((sum: number, j: any) => sum + (j.resumes?.[0]?.count ?? 0), 0);
 44→      const creditsUsed = (usageRes.data ?? []).reduce((sum: number, u: any) => sum + (u.credits_used ?? 0), 0);
 45→      setStats({ totalJobs, totalResumes, creditsUsed });
 46→    } catch { /* silent */ }
 47→  }, [user]);
 48→  useEffect(() => { fetchStats(); }, [fetchStats]);
 49→
 50→  // Credits
 51→  const sub = profile?.subscription_credits ?? 0;
 52→  const top = profile?.topup_credits ?? 0;
 53→  const bonus = profile?.bonus_credits ?? 0;
 54→  const split = sub + top + bonus;
 55→  const totalCredits = split > 0 ? split : (profile?.credits ?? 0);
 56→
 57→  return (
 58→    <SidebarLayout>
 59→      <main className="mx-auto max-w-2xl px-4 sm:px-6 lg:px-8 py-8">
 60→        <FadeIn>
 61→          <h1 className="text-xl font-semibold text-foreground tracking-tight mb-6">Profile</h1>
 62→        </FadeIn>
 63→        <StaggerList className="space-y-6" stagger={0.08}>
 64→          {/* Account card */}
 65→          <Card>
 66→            <CardContent className="p-6">
 67→              <div className="flex items-center gap-4">
 68→                <div className="h-14 w-14 rounded-full bg-primary text-primary-foreground text-lg font-bold flex items-center justify-center shrink-0">
 69→                  {getInitials(user?.email)}
 70→                </div>
 71→                <div className="min-w-0 flex-1">
 72→                  <h2 className="text-lg font-semibold text-foreground truncate">{getUserName(user?.email)}</h2>
 73→                  <p className="text-sm text-muted-foreground truncate">{user?.email}</p>
 74→                  <div className="flex items-center gap-2 mt-1.5">
 75→                    <Badge variant={isPaid ? "default" : "secondary"} className="text-xs capitalize gap-1">
 76→                      {isPaid && <Crown className="h-3 w-3" />}
 77→                      {plan} plan
 78→                    </Badge>
 79→                    <Badge variant="outline" className="text-xs tabular-nums">{totalCredits} credits</Badge>
 80→                  </div>
 81→                </div>
 82→              </div>
 83→
 84→              <Separator className="my-5" />
 85→
 86→              <div className="grid grid-cols-2 gap-4 text-sm">
 87→                <div className="flex items-center gap-2.5">
 88→                  <Mail className="h-4 w-4 text-muted-foreground" />
 89→                  <div>
 90→                    <p className="text-xs text-muted-foreground">Email</p>
 91→                    <p className="text-foreground truncate">{user?.email}</p>
 92→                  </div>
 93→                </div>
 94→                <div className="flex items-center gap-2.5">
 95→                  <Calendar className="h-4 w-4 text-muted-foreground" />
 96→                  <div>
 97→                    <p className="text-xs text-muted-foreground">Member since</p>
 98→                    <p className="text-foreground">{user?.created_at ? new Date(user.created_at).toLocaleDateString("en-US", { month: "long", year: "numeric" }) : "—"}</p>
 99→                  </div>
100→                </div>
101→                <div className="flex items-center gap-2.5">
102→                  <Inbox className="h-4 w-4 text-muted-foreground" />
103→                  <div>
104→                    <p className="text-xs text-muted-foreground">Email inbox</p>
105→                    <p className="text-foreground">{profile?.email_enabled ? "Enabled" : "Disabled"}</p>
106→                  </div>
107→                </div>
108→                <div className="flex items-center gap-2.5">
109→                  <Zap className="h-4 w-4 text-muted-foreground" />
110→                  <div>
111→                    <p className="text-xs text-muted-foreground">Subscription</p>
112→                    <p className="text-foreground">{profile?.subscription_ends_at ? `Until ${new Date(profile.subscription_ends_at).toLocaleDateString("en-US", { month: "short", year: "numeric" })}` : "None"}</p>
113→                  </div>
114→                </div>
115→              </div>
116→            </CardContent>
117→          </Card>
118→
119→          {/* Usage stats */}
120→          <Card>
121→            <CardHeader className="pb-3 px-6 pt-5">
122→              <CardTitle className="text-sm font-medium">Activity</CardTitle>
123→            </CardHeader>
124→            <CardContent className="px-6 pb-5">
125→              {!stats ? (
126→                <div className="grid grid-cols-3 gap-4">
127→                  {[0, 1, 2].map((i) => (
128→                    <div key={i} className="space-y-1.5">
129→                      <Skeleton className="h-7 w-12" />
130→                      <Skeleton className="h-3 w-20" />
131→                    </div>
132→                  ))}
133→                </div>
134→              ) : (
135→                <div className="grid grid-cols-3 gap-4">
136→                  <div>
137→                    <div className="flex items-center gap-2">
138→                      <Briefcase className="h-4 w-4 text-muted-foreground" />
139→                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalJobs}</span>
140→                    </div>
141→                    <p className="text-xs text-muted-foreground mt-0.5">Jobs created</p>
142→                  </div>
143→                  <div>
144→                    <div className="flex items-center gap-2">
145→                      <FileText className="h-4 w-4 text-muted-foreground" />
146→                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalResumes}</span>
147→                    </div>
148→                    <p className="text-xs text-muted-foreground mt-0.5">Resumes ranked</p>
149→                  </div>
150→                  <div>
151→                    <div className="flex items-center gap-2">
152→                      <Zap className="h-4 w-4 text-muted-foreground" />
153→                      <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.creditsUsed}</span>
154→                    </div>
155→                    <p className="text-xs text-muted-foreground mt-0.5">Credits used</p>
156→                  </div>
157→                </div>
158→              )}
159→            </CardContent>
160→          </Card>
161→
162→          {/* Change password */}
163→          <ChangePasswordCard />
164→        </StaggerList>
165→      </main>
166→    </SidebarLayout>
167→  );
168→};
169→
170→export default Profile;
171→

